**What I found**
- In `src/api/routes.ts`, `login` starts a session with `createSession(user.id)`: the user id is the only argument, and there are no options.
- `session.ts` exports `getSession`, `revokeSession`, `createSession` and `resetSessions`. The last one is the test helper that `session.test.ts` calls in `beforeEach`.
- Tests use `node:test` with `node:assert/strict` and import with `.ts` extensions. They run via `node --test`.

**`src/auth/refresh.ts`**
```ts
import { createSession, getSession, revokeSession, type Session } from "./session.ts";

/** Swap a live session for a fresh one for the same user; undefined if the token isn't live. */
export function refreshSession(token: string): Session | undefined {
  const current = getSession(token);
  if (!current) return undefined;
  revokeSession(current.token);
  return createSession(current.userId);
}
```

**`test/refresh.test.ts`**
```ts
import { test, beforeEach } from "node:test";
import assert from "node:assert/strict";
import { createSession, getSession, resetSessions } from "../src/auth/session.ts";
import { refreshSession } from "../src/auth/refresh.ts";

beforeEach(() => resetSessions());

test("refreshSession revokes the old token and issues a new one for the same user", () => {
  const old = createSession("u_1");
  const fresh = refreshSession(old.token);
  assert.ok(fresh);
  assert.equal(fresh.userId, "u_1");
  assert.notEqual(fresh.token, old.token);
  assert.equal(getSession(old.token), undefined);
  assert.equal(getSession(fresh.token)?.userId, "u_1");
});

test("refreshSession returns undefined for an unknown token", () => {
  assert.equal(refreshSession("nope"), undefined);
});

test("refreshSession returns undefined for a revoked token", () => {
  const s = createSession("u_2");
  assert.ok(refreshSession(s.token));
  assert.equal(refreshSession(s.token), undefined);
});
```

